template:
enum Event {
    Click(i64, i64),
    Key(char),
}

fn describe(e: &Event) -> String {
    match e {
        ⟦click_pat⟧ => format!("click at {x},{y}"),
        ⟦key_pat⟧ => format!("key {c}"),
    }
}

fn main() {
    println!("{}", describe(&Event::Click(3, 9)));
    println!("{}", describe(&Event::Key('q')));
}

tests:
#[test]
fn describes() {
    assert_eq!(describe(&Event::Click(3, 9)), "click at 3,9");
    assert_eq!(describe(&Event::Key('q')), "key q");
}
